with c as (select id from public.academy_courses where id='meteorology-forecasting-foundations'),
ch as (insert into public.academy_chapters(course_id,title,description,sort_order,published) select id,'الإشعاع الجوي والفيزياء والكيمياء الجوية','الإشعاع الشمسي والأرضي وانتقال الطاقة والميزانية السطحية والهباء والأوزون والكيمياء الجوية والطبقة الحدية.',20,false from c on conflict(course_id,title) do update set description=excluded.description returning id),
u1 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'أساسيات الإشعاع الجوي',1,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u2 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'فيزياء السطح والطبقة الحدية',2,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u3 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'كيمياء الغلاف الجوي والإشعاع',3,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
d(slug,title,summary,content,ord,mins,objectives,unit) as (values ('solar-and-terrestrial-radiation','الإشعاع الشمسي والإشعاع الأرضي','مصادر الإشعاع ومكوناته والميزانية الإشعاعية للأرض والغلاف الجوي.','{"blocks":[{"type":"text","text":"تصل الطاقة إلى نظام الأرض أساساً على هيئة إشعاع شمسي قصير الموجة، بينما تصدر الأرض والغلاف الجوي إشعاعاً حرارياً طويل الموجة."},{"type":"text","text":"يتغير الإشعاع الشمسي الواصل إلى سطح الأرض مع زاوية الشمس وطول النهار والسحب والهباء والامتصاص والتشتت."},{"type":"text","text":"يشمل الإشعاع الشمسي المباشر الإشعاع القادم من قرص الشمس، بينما يمثل المنتشر الإشعاع الذي تشتت في الغلاف الجوي ووصل من اتجاهات متعددة."},{"type":"text","text":"يمثل الإشعاع الشمسي الكلي على سطح أفقي مجموع المكونين المباشر والمنتشر وفق هندسة القياس."},{"type":"text","text":"تعكس الأسطح جزءاً من الإشعاع الساقط وفق البياض Albedo، ويختلف البياض بين الثلج والماء والتربة والغطاء النباتي."},{"type":"text","text":"تمتص الغازات والسحب والهباء أجزاء من الإشعاع الشمسي، وتختلف أطوال الموجات التي تتفاعل معها."},{"type":"text","text":"تصدر الأرض إشعاعاً حرارياً يعتمد على درجة حرارة سطحها وخصائص انبعاثه."},{"type":"text","text":"تمتص الغازات الدفيئة والسحب الإشعاع الأرضي وتعيد إصدار جزء منه، ما يؤثر في توازن الطاقة الرأسي."},{"type":"text","text":"تعرف الميزانية الإشعاعية بأنها الفرق بين الطاقة الإشعاعية الداخلة والخارجة عند سطح أو قمة الغلاف الجوي."},{"type":"text","text":"تؤثر زاوية الشمس والغطاء السحابي والبياض في التباين اليومي والموسمي والمكاني للطاقة المتاحة."},{"type":"text","text":"مثال: الثلج يعكس نسبة كبيرة من الإشعاع الشمسي مقارنة بسطح داكن، ما يؤثر في الطاقة الممتصة والذوبان."},{"type":"callout","text":"خلاصة: الإشعاع هو المحرك الأساسي لميزانية الطاقة والطقس والمناخ."}]}',1260,55,'["تمييز الإشعاع القصير والطويل","شرح مكونات الإشعاع السطحي","فهم الميزانية الإشعاعية"]','أساسيات الإشعاع الجوي'),
('radiative-transfer-in-atmosphere','انتقال الإشعاع في الغلاف الجوي','الامتصاص والانبعاث والتشتت والنوافذ الطيفية ودور الغازات والسحب.','{"blocks":[{"type":"text","text":"ينتقل الإشعاع خلال الغلاف الجوي عبر عمليات الامتصاص والانبعاث والتشتت والانعكاس."},{"type":"text","text":"يعتمد امتصاص الإشعاع على طول الموجة ونوع الغاز وتركيزه ودرجة الحرارة والضغط."},{"type":"text","text":"تمتص جزيئات الأوزون أجزاء مهمة من الأشعة فوق البنفسجية، بينما تمتص غازات أخرى نطاقات من الأشعة تحت الحمراء."},{"type":"text","text":"تمتص جزيئات بخار الماء وثاني أكسيد الكربون الإشعاع الحراري في نطاقات طيفية متعددة."},{"type":"text","text":"يعرف الانبعاث بأنه إصدار المادة للإشعاع نتيجة حالتها الحرارية، ويتأثر بدرجة الحرارة والخصائص الطيفية."},{"type":"text","text":"يغير التشتت اتجاه انتشار الإشعاع دون أن يعني بالضرورة امتصاص طاقته، ويعتمد على حجم الجسيمات وطول الموجة."},{"type":"text","text":"يسهم تشتت رايلي للجزيئات الصغيرة في تفضيل تشتت الأطوال الموجية القصيرة في المجال المرئي."},{"type":"text","text":"يصف تشتت مي علاقة الإشعاع بجسيمات أكبر مثل قطرات السحب والهباء، ويكون أقل اعتماداً على طول الموجة في بعض النطاقات."},{"type":"text","text":"توجد نوافذ طيفية تسمح بمرور نسبي لبعض نطاقات الإشعاع عبر الغلاف الجوي مقارنة بنطاقات الامتصاص القوي."},{"type":"text","text":"تستخدم نماذج انتقال الإشعاع لحساب التدفقات وتأثيرها في التسخين الجوي ومخرجات الأقمار الصناعية."},{"type":"text","text":"مثال: تختلف استجابة قناتين فضائيتين بسبب اختلاف امتصاص الغازات في نطاقيهما الطيفيين."},{"type":"callout","text":"خلاصة: فهم انتقال الإشعاع ضروري لتفسير التسخين الجوي والاستشعار عن بعد والميزانية المناخية."}]}',1270,55,'["شرح الامتصاص والانبعاث","فهم التشتت الجوي","التعرف إلى النوافذ الطيفية"]','أساسيات الإشعاع الجوي'),
('surface-energy-balance-and-fluxes','ميزانية الطاقة السطحية والتدفقات الحرارية','توازن الإشعاع والحرارة المحسوسة والكامنة وتدفق حرارة التربة.','{"blocks":[{"type":"text","text":"تصف ميزانية الطاقة السطحية كيفية توزيع الطاقة الصافية بين تسخين الهواء والتبخر وتسخين التربة والتخزين."},{"type":"text","text":"يشير الإشعاع الصافي إلى الفرق بين الإشعاع الداخل والخارج عند السطح، ويضم المكونات القصيرة والطويلة الموجة."},{"type":"text","text":"يمثل التدفق الحراري المحسوس انتقال الطاقة بين السطح والهواء عبر فرق الحرارة والخلط."},{"type":"text","text":"يمثل التدفق الحراري الكامن الطاقة المرتبطة بتبخر الماء أو تكاثفه، ويرتبط بتوفر الرطوبة والطلب التبخري."},{"type":"text","text":"ينتقل جزء من الطاقة إلى التربة أو منها بحسب فرق الحرارة والخصائص الحرارية والظروف اليومية."},{"type":"text","text":"قد تشمل الميزانية تغيرات التخزين في الغطاء النباتي والمباني والماء بحسب نوع السطح والنموذج المستخدم."},{"type":"text","text":"تؤثر رطوبة التربة في تقسيم الطاقة بين التدفق المحسوس والكامن؛ فالتربة الرطبة تدعم التبخر أكثر عند توفر الطاقة."},{"type":"text","text":"تختلف ميزانية الطاقة بين المدينة والغابة والصحراء والبحر والغطاء الثلجي."},{"type":"text","text":"تتحكم ميزانية الطاقة في تطور الطبقة الحدية ودرجة حرارة السطح ومعدلات التبخر والخلط."},{"type":"text","text":"تستخدم قياسات التدفقات مثل تقنية eddy covariance في بعض المواقع لدراسة تبادل الطاقة والمواد بين السطح والغلاف الجوي."},{"type":"text","text":"مثال: بعد هطول المطر قد يزداد التدفق الكامن ويقل التسخين المحسوس مقارنة بفترة جفاف سابقة."},{"type":"callout","text":"خلاصة: توازن الطاقة السطحية يربط الطقس بخصائص الأرض والرطوبة والغطاء النباتي."}]}',1280,55,'["شرح مكونات ميزانية الطاقة","تمييز التدفقات الحرارية","فهم أثر السطح في الطبقة الحدية"]','فيزياء السطح والطبقة الحدية'),
('aerosols-and-atmospheric-optics','الهباء الجوي والبصريات الجوية','الجسيمات العالقة ومصادرها وتأثيرها في الرؤية والإشعاع والسحب.','{"blocks":[{"type":"text","text":"الهباء الجوي جسيمات صلبة أو قطرات سائلة دقيقة معلقة في الهواء، ولها مصادر طبيعية وبشرية."},{"type":"text","text":"تشمل المصادر الطبيعية الغبار والملح البحري والدخان البركاني وبعض الجسيمات الحيوية."},{"type":"text","text":"تشمل المصادر البشرية الاحتراق والصناعة والنقل وبعض الأنشطة الزراعية."},{"type":"text","text":"يتغير عمر الجسيمات ومسارها بحسب حجمها وتركيبها والرطوبة والرياح وعمليات الترسيب."},{"type":"text","text":"تشتت الجسيمات وامتصاصها للإشعاع يغيران الرؤية والميزانية الإشعاعية ودرجة حرارة الغلاف الجوي."},{"type":"text","text":"يصف العمق البصري للهباء مقدار إضعاف الإشعاع خلال مروره في عمود الهواء، ولا يساوي تركيز الجسيمات السطحي مباشرة."},{"type":"text","text":"قد تزيد الرطوبة حجم بعض الجسيمات الاسترطابية وتغير خصائصها البصرية."},{"type":"text","text":"يمكن لبعض الجسيمات أن تعمل نوى تكاثف للسحب أو نوى تجمد، فتؤثر في خصائص السحب والهطول."},{"type":"text","text":"تستخدم الأقمار ومحطات قياس الجسيمات والليدار والرصد البصري لمتابعة الهباء."},{"type":"text","text":"تحتاج مقارنة منتجات الهباء إلى فهم طول الموجة وطريقة الاسترجاع والسطح والغيوم وجودة الرصد."},{"type":"text","text":"مثال: قد يسجل القمر عمقاً بصرياً مرتفعاً بسبب طبقة غبار مرتفعة حتى لو لم يكن التركيز السطحي مماثلاً."},{"type":"callout","text":"خلاصة: الهباء عنصر مهم في جودة الهواء والإشعاع وتكوين السحب والاستشعار الفضائي."}]}',1290,55,'["تصنيف مصادر الهباء","فهم أثر الجسيمات في الإشعاع","تمييز العمق البصري عن التركيز"]','فيزياء السطح والطبقة الحدية'),
('ozone-layer-and-ultraviolet-radiation','طبقة الأوزون والأشعة فوق البنفسجية','توزيع الأوزون ودوره الإشعاعي ومؤشر الأشعة فوق البنفسجية.','{"blocks":[{"type":"text","text":"يوجد معظم أوزون الغلاف الجوي في الستراتوسفير، حيث يمتص جزءاً مهماً من الأشعة فوق البنفسجية الشمسية."},{"type":"text","text":"يسهم الأوزون في حماية الكائنات الحية من جزء من الأشعة فوق البنفسجية ذات الطاقة العالية."},{"type":"text","text":"يتكون الأوزون ويتفكك عبر تفاعلات ضوئية وكيميائية تتأثر بالإشعاع والحرارة والمواد المحفزة."},{"type":"text","text":"تختلف كمية الأوزون رأسياً وموسمياً وجغرافياً، وتؤثر حركة الستراتوسفير في توزيعه."},{"type":"text","text":"تؤثر المواد المستنفدة للأوزون في كيمياء الستراتوسفير، وقد ساهمت المركبات المحتوية على الكلور والبروم في استنزافه تاريخياً."},{"type":"text","text":"يصف عمود الأوزون الكمية الكلية في عمود هوائي فوق الموقع، وغالباً يعبر عنه بوحدة دوبسون."},{"type":"text","text":"تتغير الأشعة فوق البنفسجية عند السطح مع زاوية الشمس وعمود الأوزون والسحب والهباء والارتفاع والانعكاس السطحي."},{"type":"text","text":"مؤشر الأشعة فوق البنفسجية مقياس مبسط لشدة الأشعة فوق البنفسجية المؤثرة حيوياً عند السطح."},{"type":"text","text":"قد تختلف قيمة UV بين السماء الصافية والغائمة، كما قد تزيد الأسطح العاكسة التعرض في بعض الظروف."},{"type":"text","text":"تستخدم الأقمار وأجهزة قياس الأوزون الأرضية لمراقبة التوزيع والاتجاهات."},{"type":"text","text":"مثال: ارتفاع الموقع عن سطح البحر قد يزيد الأشعة فوق البنفسجية الواصلة مقارنة بموقع أخفض تحت ظروف متقاربة."},{"type":"callout","text":"خلاصة: الأوزون عنصر رئيسي في كيمياء الستراتوسفير وفي تحديد الأشعة فوق البنفسجية عند السطح."}]}',1300,55,'["شرح توزيع الأوزون","فهم امتصاص الأشعة فوق البنفسجية","قراءة مؤشر UV"]','كيمياء الغلاف الجوي والإشعاع'),
('atmospheric-chemistry-and-photochemical-smog','كيمياء الغلاف الجوي والضباب الدخاني الضوئي','التفاعلات الكيميائية للملوثات وتكوين الأوزون التروبوسفيري.','{"blocks":[{"type":"text","text":"تدرس كيمياء الغلاف الجوي مصادر الغازات والجسيمات وتفاعلاتها وانتقالها وإزالتها."},{"type":"text","text":"يختلف الأوزون التروبوسفيري عن أوزون الستراتوسفير؛ فالأول ملوث ثانوي قرب السطح والثاني يحمي من الأشعة فوق البنفسجية."},{"type":"text","text":"يتكون الأوزون قرب السطح عبر تفاعلات ضوئية تشمل أكاسيد النيتروجين والمركبات العضوية المتطايرة بوجود ضوء الشمس."},{"type":"text","text":"تتغير سرعة التفاعلات مع شدة الإشعاع ودرجة الحرارة وتركيز المواد الأولية والظروف الجوية."},{"type":"text","text":"قد يؤدي الاستقرار وضعف التهوية إلى تراكم الملوثات الأولية والثانوية في الطبقة القريبة من السطح."},{"type":"text","text":"تؤثر الرياح في نقل الملوثات من مناطق الانبعاث إلى مناطق أخرى، وقد تتكون مستويات مرتفعة بعيداً عن المصدر."},{"type":"text","text":"تسهم المركبات العضوية المتطايرة في كيمياء الأوزون والجسيمات الثانوية، وتختلف تفاعلاتها بحسب تركيبها."},{"type":"text","text":"قد يؤدي الإشعاع القوي والحرارة المرتفعة إلى زيادة ظروف تكوين الضباب الدخاني الضوئي في بعض البيئات."},{"type":"text","text":"تستخدم نماذج الكيمياء والنقل لتمثيل الانبعاثات والتفاعلات والترسيب."},{"type":"text","text":"تحتاج دراسة جودة الهواء إلى قياسات متزامنة للأوزون وأكاسيد النيتروجين والطقس ومصادر الانبعاث."},{"type":"text","text":"مثال: قد ترتفع تراكيز الأوزون بعد الظهر في بيئة مشمسة ذات سلائف كيميائية كافية، مع اختلاف النمط بحسب الموقع."},{"type":"callout","text":"خلاصة: جودة الهواء ناتج عن تفاعل الكيمياء والانبعاثات والطقس وليس عن عامل منفرد."}]}',1310,55,'["شرح التفاعلات الضوئية","فهم تكوين الأوزون الأرضي","تمييز الأوزون الستراتوسفيري والتروبوسفيري"]','كيمياء الغلاف الجوي والإشعاع'),
('boundary-layer-turbulence-and-mixing','اضطراب الطبقة الحدية والخلط الرأسي','الدوامات الصغيرة والتدفقات المضطربة وارتفاع طبقة الخلط.','{"blocks":[{"type":"text","text":"الطبقة الحدية الجوية تتفاعل مباشرة مع سطح الأرض عبر الاحتكاك والتدفقات الحرارية والرطوبية خلال مدد قصيرة."},{"type":"text","text":"يتكون الاضطراب من حركات دوامية غير منتظمة تنقل الزخم والحرارة والرطوبة والملوثات."},{"type":"text","text":"ينشأ الاضطراب الميكانيكي بفعل قص الرياح والعوائق وخشونة السطح."},{"type":"text","text":"ينشأ الاضطراب الحراري عندما يؤدي تسخين السطح إلى طفو وحركة حملية صاعدة."},{"type":"text","text":"تحد الطبقات المستقرة من الحركة الرأسية وتقلل الخلط، بينما تدعم الظروف غير المستقرة الخلط العميق."},{"type":"text","text":"يتغير ارتفاع طبقة الخلط خلال اليوم؛ فيزداد غالباً مع التسخين النهاري وقد ينخفض ليلاً مع الاستقرار."},{"type":"text","text":"تؤثر السحب والرياح والتضاريس ورطوبة التربة في بنية الطبقة الحدية."},{"type":"text","text":"تستخدم ملفات الحرارة والرياح والليدار والرادار والسبر لتقدير بنية الخلط وارتفاع الطبقة."},{"type":"text","text":"تحتاج النماذج العددية إلى مخططات اضطراب لتمثيل الحركات الأصغر من الشبكة."},{"type":"text","text":"يؤثر ارتفاع الخلط في تشتت الملوثات وتطور السحب الحملية وتبادل الطاقة مع السطح."},{"type":"text","text":"مثال: قد يزداد ارتفاع طبقة الخلط بعد شروق الشمس مع تسخين السطح وتطور الحمل الحراري."},{"type":"callout","text":"خلاصة: الاضطراب هو آلية رئيسية لنقل الخصائص الجوية داخل الطبقة الحدية."}]}',1320,55,'["شرح الاضطراب الجوي","تمييز الاستقرار عن الخلط","فهم ارتفاع طبقة الخلط"]','فيزياء السطح والطبقة الحدية'),
('cloud-radiative-effects-and-feedbacks','التأثير الإشعاعي للسحب والتغذية الراجعة','انعكاس السحب للإشعاع الشمسي وامتصاصها للإشعاع الأرضي.','{"blocks":[{"type":"text","text":"تؤثر السحب في ميزانية الطاقة عبر عكس وامتصاص وإصدار الإشعاع عند أطوال موجية مختلفة."},{"type":"text","text":"تعكس السحب جزءاً من الإشعاع الشمسي إلى الفضاء، ما يؤدي غالباً إلى تأثير تبريدي في النظام الأرضي."},{"type":"text","text":"تمتص السحب الإشعاع الأرضي طويل الموجة وتصدره بدرجات حرارة تتعلق بارتفاعها وخصائصها."},{"type":"text","text":"قد يكون التأثير الصافي للسحب تبريدياً أو تدفئياً بحسب الارتفاع والسمك والطور والوقت والسطح أسفلها."},{"type":"text","text":"تكون السحب العالية الرقيقة قادرة على التأثير في الإشعاع طويل الموجة مع انعكاس شمسي محدود نسبياً."},{"type":"text","text":"تؤثر السحب المنخفضة السميكة غالباً في زيادة انعكاس الإشعاع الشمسي، وقد يكون أثرها التبريدي مهماً."},{"type":"text","text":"تغير السحب توزيع الطاقة الرأسية وقد تؤثر في استقرار الطبقة الحدية والهطول."},{"type":"text","text":"تصف التغذية الراجعة السحابية كيفية تغير السحب استجابة لتغير الحرارة والرطوبة والدوران، ثم تأثيرها في المناخ."},{"type":"text","text":"يصعب تمثيل بعض خصائص السحب في النماذج بسبب صغر مقاييسها وتنوع أشكالها وعملياتها الدقيقة."},{"type":"text","text":"تستخدم القياسات الفضائية والأرضية لتقدير الغطاء السحابي والخصائص البصرية والارتفاع ودرجة حرارة القمم."},{"type":"text","text":"مثال: زيادة الغطاء السحابي المنخفض نهاراً قد تقلل الإشعاع الشمسي الواصل للسطح، بينما تختلف النتيجة ليلاً."},{"type":"callout","text":"خلاصة: أثر السحب الإشعاعي يعتمد على خصائصها وطيف الإشعاع والظروف المحيطة."}]}',1330,55,'["شرح الأثر القصير والطويل الموجة للسحب","فهم أثر ارتفاع السحب وسمكها","تمييز التغذية الراجعة السحابية"]','فيزياء السطح والطبقة الحدية'),
('atmospheric-greenhouse-effect','تأثير الاحتباس الحراري الطبيعي والاحترار المعزز','آلية امتصاص الإشعاع الأرضي ودور الغازات الدفيئة والميزانية الطاقية.','{"blocks":[{"type":"text","text":"يمتص سطح الأرض الإشعاع الشمسي ويصدر طاقة حرارية طويلة الموجة إلى الغلاف الجوي والفضاء."},{"type":"text","text":"تمتص غازات دفيئة مثل بخار الماء وثاني أكسيد الكربون والميثان وأكسيد النيتروز أجزاء من الإشعاع الحراري عند نطاقات طيفية محددة."},{"type":"text","text":"تعيد الغازات الدفيئة إصدار الإشعاع في اتجاهات متعددة، بما في ذلك نحو السطح، ما يرفع حرارة السطح والطبقات السفلى مقارنة بحالة غياب هذا التأثير."},{"type":"text","text":"الاحتباس الحراري الطبيعي ضروري للحفاظ على درجات حرارة ملائمة للحياة كما نعرفها."},{"type":"text","text":"تؤدي زيادة تركيز بعض الغازات بفعل الأنشطة البشرية إلى تعزيز التأثير الإشعاعي وتغيير توازن الطاقة."},{"type":"text","text":"يعبر التأثير الإشعاعي عن تغير صافي تدفق الطاقة عند مستوى مرجعي نتيجة تغير عامل مؤثر، وفق تعريفات القياس والحساب."},{"type":"text","text":"تختلف الغازات في قدرتها على امتصاص الإشعاع وفي مدة بقائها الجوية، ولذلك تختلف مساهماتها في الاحترار."},{"type":"text","text":"تؤثر السحب والهباء والتغيرات السطحية في الميزانية الإشعاعية، وقد تكون آثارها معقدة ومكانية."},{"type":"text","text":"تستجيب درجة حرارة النظام ببطء نسبياً بسبب السعة الحرارية للمحيطات وتبادل الطاقة بين مكونات النظام المناخي."},{"type":"text","text":"تستخدم القياسات الطيفية والأقمار والنماذج لتقدير التدفقات والتركيزات والتغيرات الإشعاعية."},{"type":"text","text":"مثال: زيادة تركيز ثاني أكسيد الكربون تعزز امتصاص الإشعاع الأرضي ضمن نطاقاته الطيفية، ثم يستجيب النظام المناخي عبر تعديلات متعددة."},{"type":"callout","text":"خلاصة: الاحتباس الحراري يفسر جزءاً أساسياً من توازن الطاقة، بينما يحدد التغير في تركيز الغازات مسار التأثير المعزز."}]}',1340,55,'["شرح الاحتباس الحراري الطبيعي","تمييز التأثير الإشعاعي عن تغير الحرارة","فهم الغازات الدفيئة"]','كيمياء الغلاف الجوي والإشعاع'),
('atmospheric-electricity-and-ionosphere','كهرباء الغلاف الجوي والأيونوسفير','المجال الكهربائي الجوي والتفريغ الرعدي والطبقات المتأينة.','{"blocks":[{"type":"text","text":"يحتوي الغلاف الجوي على شحنات وأيونات وجسيمات مشحونة تؤثر في خصائصه الكهربائية."},{"type":"text","text":"توجد قرب سطح الأرض حقول كهربائية جوية ضعيفة تتغير مع الطقس والهباء والتلوث والعواصف."},{"type":"text","text":"تعمل العواصف الرعدية على فصل الشحنات داخل السحب وتنتج تفريغات كهربائية بين مناطق الشحنة."},{"type":"text","text":"يسهم البرق في إعادة توزيع الشحنات بين السحب والأرض والغلاف الجوي."},{"type":"text","text":"تعرف الدائرة الكهربائية العالمية بأنها منظومة تبادل كهربائي بين سطح الأرض والغلاف الجوي العلوي، وتتأثر بالعواصف الرعدية العالمية."},{"type":"text","text":"الأيونوسفير منطقة من الغلاف الجوي العلوي تحتوي تركيزاً مهماً من الأيونات والإلكترونات الحرة بفعل التأين الشمسي."},{"type":"text","text":"لا تتطابق حدود الأيونوسفير تماماً مع تقسيم الطبقات الحرارية، إذ تعتمد على معيار التأين والظروف الشمسية."},{"type":"text","text":"تؤثر الأشعة فوق البنفسجية والأشعة السينية والنشاط الشمسي في درجة تأين الطبقات العليا."},{"type":"text","text":"تؤثر التغيرات في الأيونوسفير في انتشار موجات الراديو والاتصالات والملاحة بالأقمار الصناعية."},{"type":"text","text":"تستخدم أجهزة قياس المجال الكهربائي والرصد الراديوي والأقمار لدراسة خصائص الطبقات المتأينة."},{"type":"text","text":"مثال: قد تؤدي اضطرابات الأيونوسفير إلى تغيرات في دقة تحديد الموقع عبر الأقمار الصناعية أو جودة الاتصالات الراديوية."},{"type":"callout","text":"خلاصة: الكهرباء الجوية والأيونوسفير يربطان الطقس والبرق والفضاء القريب والاتصالات."}]}',1350,55,'["التعرف إلى المجال الكهربائي الجوي","شرح دور العواصف في الدائرة الكهربائية","تمييز الأيونوسفير عن الطبقات الحرارية"]','كيمياء الغلاف الجوي والإشعاع'))
insert into public.academy_lessons(course_id,chapter_id,unit_id,slug,title,summary,content,published,sort_order,level,estimated_minutes,learning_objectives,chapter_title,unit_title)
select c.id,ch.id,case d.unit when 'أساسيات الإشعاع الجوي' then u1.id when 'فيزياء السطح والطبقة الحدية' then u2.id when 'كيمياء الغلاف الجوي والإشعاع' then u3.id end,d.slug,d.title,d.summary,d.content::jsonb,false,d.ord,'advanced',d.mins,d.objectives::jsonb,'الإشعاع الجوي والفيزياء والكيمياء الجوية',d.unit from d cross join c cross join ch cross join u1 cross join u2 cross join u3
on conflict(course_id,slug) do update set chapter_id=excluded.chapter_id,unit_id=excluded.unit_id,title=excluded.title,summary=excluded.summary,content=excluded.content,published=false,sort_order=excluded.sort_order,level=excluded.level,estimated_minutes=excluded.estimated_minutes,learning_objectives=excluded.learning_objectives,chapter_title=excluded.chapter_title,unit_title=excluded.unit_title;